import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            round_spans([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        # 09:07 -> 09:00 and 17:08 -> 17:15 on a quarter hour
        self.assertEqual(
            round_spans([Span(547, 1028)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_go_up(self):
        self.assertEqual(
            round_spans([Span(60, 127)], 30),
            ["01:00-02:00 (1h 0m)"]
        )
        self.assertEqual(
            round_spans([Span(60, 135)], 30),
            ["01:00-02:30 (1h 30m)"]
        )

    def test_one_label_per_span_in_order(self):
        labels = round_spans(
            [Span(480, 720), Span(60, 120)], 60
        )
        self.assertEqual(
            labels,
            ["08:00-12:00 (4h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_end_of_day(self):
        self.assertEqual(
            round_spans([Span(1400, 1439)], 30),
            ["23:30-24:00 (0h 30m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_good_steps_accepted(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(
                    len(round_spans([Span(60, 180)], step)), 1
                )

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(61, 69)], 60)
